    sum_of_weights = sum(weights)
    if not (0.999 <= sum_of_weights <= 1.001):
        raise ValueError(f"Weights must sum to 1. Current sum: {sum_of_weights}")

    weighted_index = sum(price * weight for price, weight in zip(prices, weights))

    return round(weighted_index, 2)

